inline SoundPcm SoundData(Sound sound) {
    switch(sound) {
    case Sound::Recording: return {kRecordingSound, sizeof(kRecordingSound)/sizeof(int16_t)};
    case Sound::Question: return {kQuestionSound, sizeof(kQuestionSound)/sizeof(int16_t)};
    case Sound::Result: return {kResultSound, sizeof(kResultSound)/sizeof(int16_t)};
    case Sound::Error: return {kErrorSound, sizeof(kErrorSound)/sizeof(int16_t)};
    }
    return {nullptr,0};
}
